CREATE TABLE account (id bigint PRIMARY KEY, email text, password text, password_hash text, password_salt text);
CREATE TABLE web_domain (id bigint PRIMARY KEY, name text, is_use_free_cert boolean NOT NULL, is_verified boolean NOT NULL, free_cert_message text);
CREATE TABLE website (id bigint PRIMARY KEY, name text, specifications jsonb, hosts jsonb, proxy_rules jsonb, create_time timestamptz NOT NULL, update_time timestamptz NOT NULL, proxy_transforms jsonb, simple_responses jsonb);
CREATE TABLE resource_monitor_info (resource_uuid text NOT NULL, session_key text, create_ts bigint NOT NULL, data jsonb, PRIMARY KEY (resource_uuid, create_ts));
CREATE TABLE resource_report (resource_uuid text NOT NULL, cycle_type integer NOT NULL, report_time timestamptz NOT NULL, report_ts bigint NOT NULL, request_qty bigint NOT NULL, status_code jsonb, spider jsonb, browser jsonb, os jsonb, duration jsonb, create_time timestamptz NOT NULL, update_time timestamptz NOT NULL, PRIMARY KEY (resource_uuid, cycle_type, report_ts));
CREATE TABLE account_password_recovery (id bigint PRIMARY KEY, recovery_id text NOT NULL UNIQUE, account_id bigint NOT NULL, account_email text NOT NULL, email_verified boolean NOT NULL, code_hash text, code_salt text, code_expire_ts bigint, failed_attempts integer NOT NULL, status integer NOT NULL, create_ts bigint NOT NULL, update_ts bigint NOT NULL);
CREATE TABLE host_traffic (id bigint PRIMARY KEY, host_name text, period bigint NOT NULL, request_counts bigint NOT NULL, inbound_bytes bigint NOT NULL, outbound_bytes bigint NOT NULL);
CREATE TABLE request_history (id bigint PRIMARY KEY, request_time timestamptz NOT NULL, request_ts bigint NOT NULL, duration_ms bigint NOT NULL, client_ip text, method text, scheme text, host text, path text, query_string text, url text, protocol text, status_code integer NOT NULL, user_agent text, proxy_stage text, exception_stage text, forwarder_error text, request_headers jsonb, response_headers jsonb, request_body_base64 text, response_body_base64 text, request_content_type text, response_content_type text, request_body_truncated boolean NOT NULL DEFAULT false, response_body_truncated boolean NOT NULL DEFAULT false, exception_type text, exception_message text, exception_stack_trace text);
